#!/usr/bin/env python3
"""The small (3-armed) Gaunt's Pixel Lab clips (ArtSource/mutants_anim/gaunt/pixellab/small, README there) -> game strips + timing table (2026-11-19), the same cell rule as export_elder_clips.py:
210x110 cells, the standing sprite (98x98, mutant_hd_gaunt.png) with its bottom on the cell bottom and its centre on the cell centre (the 160x120 Pixel Lab frames carry it at (6,12)), frames that dip below the feet lifted by the overshoot.
python3 ArtSource/export_small_gaunt_clips.py -> Assets/Resources/Sprites/Mutants/anim/gaunt_<clip>.bytes + Assets/Scripts/GameCore/ElderClips.Small.cs"""
import os, io
import numpy as np
from PIL import Image
HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.dirname(HERE)
PL = os.path.join(HERE, 'mutants_anim', 'gaunt', 'pixellab', 'small'); OUT = os.path.join(ROOT, 'Assets', 'Resources', 'Sprites', 'Mutants', 'anim')
CW, CH, PX = 210, 110, 50
def cell(path):
    cv = Image.open(path).convert('RGBA'); a = np.array(cv); low = int(np.nonzero(a[..., 3].any(axis=1))[0].max()); lift = max(0, low - (CH - 1))
    out = Image.new('RGBA', (CW, CH), (0, 0, 0, 0)); out.alpha_composite(cv.crop((0, lift, 160, lift + CH)), (PX, 0)); return out
clips = {}
def add(name, frames, steps, ms, contacts=None):
    assert len(steps) == len(ms); clips[name] = dict(frames=frames, steps=steps, ms=ms, contacts=contacts or [])
cum = lambda ms, i: sum(ms[:i])
add('rise', [cell(os.path.join(PL, 'rise', 'rise_%d.png' % k)) for k in range(13)], list(range(13)), [160, 150, 150, 150, 150, 140, 130, 120, 110, 110, 120, 160, 300])
st_ms = [100, 120, 130, 110, 70, 90, 100, 110, 110, 90, 70, 100, 260]
add('stab', [cell(os.path.join(PL, 'combo2', 'c2_%d.png' % k)) for k in range(13)], list(range(13)), st_ms, [cum(st_ms, 4), cum(st_ms, 10)])
names = ['GS0', 'GS1', 'GS2', 'GS3', 'GS4', 'GW1', 'GW2', 'GW3', 'GW4', 'GW5', 'GW6', 'GW7', 'GW8']       # unique cells; the backhand plays them backwards
sw = ['GS0', 'GS1', 'GS2', 'GS3', 'GS4', 'GW1', 'GW2', 'GW3', 'GW4', 'GW5', 'GW6', 'GW7', 'GW8', 'GW7', 'GW6', 'GW5', 'GW4', 'GW3', 'GW2', 'GW1', 'GS3', 'GS2', 'GS1', 'GS0']
sw_ms = [100, 110, 120, 120, 130, 70, 60, 50, 50, 80, 90, 90, 120, 60, 50, 50, 40, 40, 60, 80, 100, 100, 100, 150]
add('swipe', [cell(os.path.join(PL, 'swipe', n + '.png')) for n in names], [names.index(n) for n in sw], sw_ms, [cum(sw_ms, 7), cum(sw_ms, 16)])
add('death', [cell(os.path.join(PL, 'death', 'death_%d.png' % k)) for k in range(13)], list(range(13)), [120, 120, 130, 150, 170, 180, 160, 140, 130, 120, 120, 200, 900])
os.makedirs(OUT, exist_ok=True)
for name, c in clips.items():
    strip = Image.new('RGBA', (CW * len(c['frames']), CH), (0, 0, 0, 0))
    for i, fr in enumerate(c['frames']): strip.alpha_composite(fr, (i * CW, 0))
    buf = io.BytesIO(); strip.save(buf, 'PNG'); open(os.path.join(OUT, 'gaunt_%s.bytes' % name), 'wb').write(buf.getvalue())
    print(name, len(c['frames']), 'cells,', len(c['steps']), 'steps,', sum(c['ms']), 'ms', c['contacts'])
A = lambda xs: ('new[] { ' + ', '.join(str(x) for x in xs) + ' }') if xs else 'new int[0]'
lines = ['// GENERATED by ArtSource/export_small_gaunt_clips.py - do not edit by hand. The small Gaunt\'s Pixel Lab clips (see ElderClips.cs).', 'using System.Collections.Generic;', '', 'namespace GameCore', '{', '    public static partial class ElderClips', '    {',
         '        public const int SmallW = %d, SmallH = %d;' % (CW, CH), '        public const float SmallPivotY = 16f / %d;' % CH, '        public static readonly Dictionary<string, Clip> Small = new Dictionary<string, Clip>', '        {']
for name, c in clips.items():
    lines.append('            ["%s"] = new Clip { Cells = %d, Step = %s, Ms = %s, Contacts = %s, TotalMs = %d },' % (name, len(c['frames']), A(c['steps']), A(c['ms']), A(c['contacts']), sum(c['ms'])))
lines += ['        };', '    }', '}']
open(os.path.join(ROOT, 'Assets', 'Scripts', 'GameCore', 'ElderClips.Small.cs'), 'w').write('\n'.join(lines) + '\n')
